[{"order":1,"type":"heading","text":"Design Patterns in PHP: A Practical Guide"},{"order":2,"type":"paragraph","text":"Design patterns are reusable solutions to commonly occurring problems in software design. They represent best practices evolved over time. This tutorial explores several key design patterns in PHP, providing practical examples for each."},{"order":3,"type":"subheading","text":"Singleton Pattern"},{"order":4,"type":"paragraph","text":"The Singleton pattern ensures that a class has only one instance and provides a global point of access to it. This is useful for managing resources like database connections or configuration settings."},{"order":5,"type":"code","text":"<?php
class Database {
  private static $instance = null;
  private $connection;

  private function __construct() {
    $this->connection = new PDO('mysql:host=localhost;dbname=mydb', 'user', 'password');
  }

  public static function getInstance() {
    if (self::$instance === null) {
      self::$instance = new Database();
    }
    return self::$instance;
  }

  public function getConnection() {
    return $this->connection;
  }
}

// Usage
$db1 = Database::getInstance();
$db2 = Database::getInstance();

var_dump($db1 === $db2); // Output: bool(true)
?>"},{"order":6,"type":"bullet_point","text":"The `__construct()` method is made private to prevent direct instantiation."},{"order":7,"type":"bullet_point","text":"The `getInstance()` method provides the global access point."},{"order":8,"type":"subheading","text":"Factory Pattern"},{"order":9,"type":"paragraph","text":"The Factory pattern provides an interface for creating objects without specifying their concrete classes. This promotes loose coupling and allows for easy extension."},{"order":10,"type":"code","text":"<?php
interface Vehicle {
  public function drive();
}

class Car implements Vehicle {
  public function drive() {
    return "Driving a car";
  }
}

class Truck implements Vehicle {
  public function drive() {
    return "Driving a truck";
  }
}

class VehicleFactory {
  public static function create(string $type): Vehicle {
    if ($type == 'car') {
      return new Car();
    } elseif ($type == 'truck') {
      return new Truck();
    } else {
      throw new Exception("Unknown vehicle type.");
    }
  }
}

// Usage
$car = VehicleFactory::create('car');
echo $car->drive(); // Output: Driving a car
?>"},{"order":11,"type":"bullet_point","text":"The `VehicleFactory` class encapsulates the object creation logic."},{"order":12,"type":"bullet_point","text":"New vehicle types can be added without modifying existing code."},{"order":13,"type":"subheading","text":"Observer Pattern"},{"order":14,"type":"paragraph","text":"The Observer pattern defines a one-to-many dependency between objects so that when one object changes state, all its dependents are notified and updated automatically. This is useful for implementing event handling systems."},{"order":15,"type":"code","text":"<?php
interface Subject {
  public function attach(Observer $observer);
  public function detach(Observer $observer);
  public function notify();
}

interface Observer {
  public function update(Subject $subject);
}

class ConcreteSubject implements Subject {
  private $observers = [];
  private $state;

  public function attach(Observer $observer) {
    $this->observers[] = $observer;
  }

  public function detach(Observer $observer) {
    $this->observers = array_filter($this->observers, function($o) use ($observer) {
      return ($o !== $observer);
    });
  }

  public function notify() {
    foreach ($this->observers as $observer) {
      $observer->update($this);
    }
  }

  public function setState($state) {
    $this->state = $state;
    $this->notify();
  }

  public function getState() {
    return $this->state;
  }
}

class ConcreteObserver implements Observer {
  private $name;

  public function __construct(string $name) {
    $this->name = $name;
  }

  public function update(Subject $subject) {
    echo "Observer {$this->name}: Subject state changed to " . $subject->getState() . "\n";
  }
}

// Usage
$subject = new ConcreteSubject();

$observer1 = new ConcreteObserver('A');
$observer2 = new ConcreteObserver('B');

$subject->attach($observer1);
$subject->attach($observer2);

$subject->setState('New State');

// Output:
// Observer A: Subject state changed to New State
// Observer B: Subject state changed to New State

$subject->detach($observer2);

$subject->setState('Another State');

// Output:
// Observer A: Subject state changed to Another State
?>"},{"order":16,"type":"bullet_point","text":"The `Subject` maintains a list of `Observer` objects."},{"order":17,"type":"bullet_point","text":"When the `Subject`'s state changes, it notifies all registered `Observer` objects."},{"order":18,"type":"paragraph","text":"These are just a few examples of the many design patterns available. Understanding and applying these patterns can lead to more maintainable, flexible, and robust PHP applications."}]
